    assert.equal(vscode.registrado.quickPick, null, 'no se pregunta nada');
    assert.equal(fs.readFileSync(path.join(roto, '.rsc.json'), 'utf8').slice(0, 7), '<<<<<<<', 'no se ha tocado');

