  await comprobar('no se elige un ejecutable de otro sistema', () => {
    const entorno = cargar('entorno');
    const carga = path.join(RAIZ, '..', 'instalador', 'windows', 'carga');
    if (!fs.existsSync(path.join(carga, 'git', 'cmd', 'git.exe'))) return 'sin carga de Windows a mano';

    const antes = process.env.EXECUTIVE_LAB_HOME;
    process.env.EXECUTIVE_LAB_HOME = carga;
    const elegido = { git: entorno.git(), node: entorno.node() };
    process.env.EXECUTIVE_LAB_HOME = antes;

    if (process.platform === 'win32') assert.match(elegido.git, /\.exe$/);
    else {
      assert.ok(!elegido.git.endsWith('.exe'), `en ${process.platform} no vale ${elegido.git}`);
      assert.ok(!elegido.node.endsWith('.exe'), `en ${process.platform} no vale ${elegido.node}`);
    }

    // Pero el filtro es solo para binarios: el punto de entrada del arnés es un
    // .js y no lleva .exe en ningún sistema. Si se filtrara, en Windows se
    // perdería el arnés preinstalado y caería a npx.
    process.env.EXECUTIVE_LAB_HOME = carga;
    const arnes = entorno.entradaDelArnes(null);
    process.env.EXECUTIVE_LAB_HOME = antes;
    assert.ok(arnes && arnes.endsWith('rsc.js'), 'el arnés preinstalado tiene que encontrarse');

    return `git → ${path.basename(elegido.git)} · arnés → rsc.js`;
  });

  await comprobar('el relevo se reconoce en un disco que no distingue mayúsculas, aunque llegue escrito de otra manera', () => {
    // Revisión de lo que pedía una persona: el macOS de fábrica no distingue
    // mayúsculas, como Windows, y el relevo en `…/relevo` con el PATH diciendo
    // `…/Relevo` se tomaba por un node del sistema. Se compara la carpeta de
    // verdad, la del disco, y no cómo se escribe; también con una barra al final.
    const relevo = cargar('relevo');
    const carpeta = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'relevo-caja-')), 'relevo');
    relevo.escribirElRelevo(carpeta, process.execPath, process.platform);
    const otra = path.join(path.dirname(carpeta), 'Relevo');
    if (!fs.existsSync(otra)) return 'SALTADA: este disco distingue mayúsculas';
    const clave = process.platform === 'win32' ? 'Path' : 'PATH';
    const env = { [clave]: [`${otra}${path.sep}`, ...String(process.env[clave] || process.env.PATH || '').split(path.delimiter).filter((d) => d && !fs.existsSync(path.join(d, 'node')) && !fs.existsSync(path.join(d, 'node.exe')))].join(path.delimiter) };
    const puesto = relevo.asegurar({ carpeta, ejecutable: process.execPath, env });
    assert.equal(puesto.modo, 'relevoVSCode', `toma su propio relevo por un node del sistema: ${JSON.stringify(puesto)}`);
    const suyas = env[clave].split(path.delimiter).filter((d) => d.replace(/[\\/]+$/, '').toLowerCase() === carpeta.toLowerCase());
    assert.equal(suyas.length, 1, `el relevo sale ${suyas.length} veces en el PATH`);
    return 'relevo y Relevo/, la misma carpeta';
  });

  await comprobar('el revisor de PowerShell caza un .Count sin @() en cualquier tubería o cmdlet', () => {
    // Revisión de lo que pedía una persona: la regla solo veía el Where-Object
    // más simple. Se le escapaban uno con paréntesis dentro, Select-String y
    // Get-ChildItem, que en PowerShell 5.1 fallan igual con un solo resultado.
    const cp = require('node:child_process');
    const MALAS = [
      '$a = ($resultados | Where-Object { $_.Ok }).Count',
      '$b = ($resultados | Where-Object { $_.Ok -and (Test-Path $_.Que) }).Count',
      "$c = (Select-String -Path $registro -Pattern 'WARN').Count",
      '$d = (Get-ChildItem $carpeta -Filter *.log).Count',
    ];
    const BUENAS = [
      '$e = @($resultados | Where-Object { $_.Ok }).Count',
      '$f = ($resultados).Count',
      'if ($malos.Count) { throw "$($malos.Count) errores" }',
    ];
    const texto = [...MALAS, ...BUENAS].join('\n');
    const r = cp.spawnSync(process.execPath, ['-e', `const r = require(${JSON.stringify(path.join(RAIZ, '..', 'herramientas', 'revisar-powershell.js'))}); process.stdout.write('\\n' + JSON.stringify(r.revisar(${JSON.stringify(texto)})))`], { encoding: 'utf8' });
    const ultima = r.stdout.trim().split('\n').pop();
    let problemas;
    try { problemas = JSON.parse(ultima); } catch { throw new Error(`el revisor no se deja usar desde una prueba: ${r.stdout.slice(0, 120)}`); }
    const marcadas = problemas.filter((p) => /Count/.test(p.que)).map((p) => p.linea);
    assert.deepEqual(marcadas, [1, 2, 3, 4], `marca las líneas ${marcadas.join(', ')} de las siete`);
    return 'las cuatro de verdad, y ninguna de las tres buenas';
  });

  await comprobar('el relevo lanza un guion con el Node de VS Code', () => {
    // C2 y la decisión 4 de Jose. RSC escribe sus enganches como `node …`, y
    // Claude Code los corre con `sh -c`. Sin un `node` en el PATH, cada
    // enganche es un error que no bloquea: la orden sigue sin freno, sin
    // brújula y sin memoria. El relevo es un `node` que llama al de VS Code,
    // como la barra ya hace para correr RSC. Vive fuera de la carpeta del
    // alumno (P8), y del anfitrión solo toca el PATH.
    if (process.platform === 'win32') return 'SALTADA: en Windows lo mide prueba/windows.js, en Git Bash, PowerShell y cmd';
    const relevo = cargar('relevo');
    const { spawnSync } = require('node:child_process');
    const carpeta = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'almacen-de-la-barra-')), 'relevo');
    const env = { PATH: '/usr/bin:/bin' };
    assert.equal(relevo.nodeDelPath(env), null, 'este PATH ya trae un node: la prueba no mira nada');

    const hecho = relevo.asegurar({ carpeta, ejecutable: process.execPath, env });
    assert.equal(hecho.modo, 'relevoVSCode');
    assert.equal(env.PATH.split(path.delimiter)[0], carpeta, 'el relevo no va delante en el PATH');
    assert.equal(env.ELECTRON_RUN_AS_NODE, undefined, 'se ha puesto ELECTRON_RUN_AS_NODE en el entorno de todos');

    // Un enganche como los de RSC, corrido como los corre Claude Code.
    const guion = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'enganche-')), 'hola.mjs');
    fs.writeFileSync(guion, "process.stdout.write('hola desde el relevo');\n");
    const dicho = spawnSync('/bin/sh', ['-c', `node "${guion}"`], { env, encoding: 'utf8' });
    assert.equal(dicho.status, 0, dicho.stderr);
    assert.equal(dicho.stdout, 'hola desde el relevo');

    // Otra vez no se duplica, y con un node de verdad en el PATH no se toca nada.
    relevo.asegurar({ carpeta, ejecutable: process.execPath, env });
    assert.equal(env.PATH.split(path.delimiter).filter((d) => d === carpeta).length, 1, 'el relevo sale dos veces en el PATH');
    const conNode = { PATH: `${path.dirname(process.execPath)}${path.delimiter}/usr/bin` };
    const antes = conNode.PATH;
    assert.equal(relevo.asegurar({ carpeta, ejecutable: process.execPath, env: conNode }).modo, 'nodeDelSistema');
    assert.equal(conNode.PATH, antes, 'con un node de verdad se ha tocado el PATH');
    return 'sin node en el PATH, el enganche corre';
  });

  await comprobar('con una versión más nueva publicada, el arranque no ofrece actualizar', () => {
    // C4. El arranque de cada conversación de RSC mira en npm si hay una
    // versión más nueva y, si la hay, le dice al asistente que ofrezca
    // `npx @ericrisco/rsc@latest`. En una clase la versión es la de la clase
    // (P7): ofrecer otra es pedirle al alumno que se salga de ella. RSC solo lo
    // apaga con `RSC_NO_UPDATE_CHECK` en el entorno del enganche.
    const relevo = cargar('relevo');
    const { spawnSync } = require('node:child_process');
    const suyo = path.join(RAIZ, 'media', 'harness', 'node_modules', '@ericrisco', 'rsc', 'targets', 'session-start.mjs');
    const raiz = fs.mkdtempSync(path.join(os.tmpdir(), 'aviso-de-version-'));
    fs.mkdirSync(path.join(raiz, '.rsc'), { recursive: true });
    fs.writeFileSync(path.join(raiz, '.rsc', '.version'), '2.0.5\n');
    // Una casa vacía: el guion de RSC mira también la del usuario.
    const casa = fs.mkdtempSync(path.join(os.tmpdir(), 'aviso-de-version-casa-'));
    const alEmpezar = (env) => spawnSync(process.execPath, [suyo, path.join(raiz, 'sin-cuerpo.md'), raiz], {
      input: '', encoding: 'utf8', env: { ...env, HOME: casa, USERPROFILE: casa, RSC_LATEST: '9.9.9' },
    });

    // Sin la barra, sale: la prueba puede fallar.
    const sinBarra = { ...process.env };
    delete sinBarra.RSC_NO_UPDATE_CHECK;
    assert.match(alEmpezar(sinBarra).stdout, /rsc update available/, 'RSC ya no avisa: la prueba no mira nada');

    // Con lo que la barra deja al abrirse, el enganche lo hereda y calla.
    const env = { PATH: process.env.PATH };
    relevo.ponerAlActivar({ carpeta: null, env });
    const dicho = alEmpezar(env);
    assert.equal(dicho.status, 0, dicho.stderr);
    assert.doesNotMatch(dicho.stdout, /rsc update available|9\.9\.9/, 'el arranque ofrece actualizar');
    return 'con la 9.9.9 publicada, el arranque calla';
  });

  await comprobar('«Algo va mal» le dice al panel que no se ha podido saber', async () => {
    // Revisión de F7, m4: que la extensión lo mande. Sin esto, el panel no sabría
    // que el diagnóstico no se pudo leer, por mucho que `soporte` lo sepa.
    const proveedor = vscode.registrado.proveedor;
    const rscM = cargar('rsc');
    const antes = { salud: rscM.salud, arreglarEnSeco: rscM.arreglarEnSeco, reevaluar: rscM.reevaluar, revisar: rscM.revisar };
    const enviarAntes = proveedor.enviar;
    const enviados = [];
    rscM.salud = async () => ({ codigo: 0, salida: 'esto no es un informe' });
    rscM.arreglarEnSeco = async () => ({ codigo: 0, salida: 'Nothing to repair' });
    rscM.reevaluar = async () => ({ codigo: 0, salida: 'RSC_REASSESSMENT_NO_CHANGE' });
    rscM.revisar = async () => ({ codigo: 0, salida: '' });
    proveedor.enviar = (m) => enviados.push(m);
    try {
      await proveedor.algoVaMal();
      const incidencia = enviados.find((m) => m.tipo === 'incidencia');
      assert.ok(incidencia, 'no se pinta la pantalla de «Algo va mal»');
      assert.equal(incidencia.sano, false);
      assert.equal(incidencia.desconocido, true, 'la extensión no le dice al panel que no se sabe');
      return 'no sano, y sin saber';
    } finally {
      Object.assign(rscM, antes);
      proveedor.enviar = enviarAntes;
    }
  });

  await comprobar('el canal de salida que usa la barra hace todo lo que hace uno de verdad', async () => {
    // La barra no escribe en el canal de VS Code a pelo: lo envuelve
    // (`rastro.envolver`) para que «Algo va mal» tenga las últimas líneas. El
    // envoltorio no tenía `clear`, y «Diagnóstico del puente» lo pide: en un
    // VS Code de verdad reventaba con «salida.clear is not a function». Los
    // dobles no lo veían porque aquí nadie lanzaba ese comando con el canal
    // envuelto; lo cazó `npm run probar-en-vscode` (28-09-2026).
    const rastro = cargar('rastro');
    const escrito = [];
    const canal = vscode.window.createOutputChannel('Executive Lab');
    const deVerdad = { ...canal, appendLine: (l) => escrito.push(l), clear: () => escrito.splice(0) };
    const envuelto = rastro.envolver(deVerdad, null);
    const faltan = Object.keys(canal).filter((m) => typeof canal[m] === 'function' && typeof envuelto[m] !== 'function');
    assert.deepEqual(faltan, [], `el canal envuelto no sabe: ${faltan.join(', ')}`);

    escrito.push('lo de antes');
    await puente.diagnostico(envuelto);
    assert.ok(!escrito.includes('lo de antes'), 'el diagnóstico no empieza limpio');
    assert.ok(escrito.some((l) => l.startsWith('=== Claude')), 'el diagnóstico no dice nada de Claude');
    return `${escrito.length} líneas, empezando limpio`;
  });

  // Las pruebas que siguen pintan la principal tal como la manda la extensión, y
  // miran sus tarjetas: en la completa, que no se ha borrado (decisión 138). Más
