    p.mandar({ ...base, origen: 'asistente', texto: 'En Construcciones Pérez no guarda', titulo: 'Construcciones Pérez: no guarda', guardado: true, hayQueEscribir: false });
    p.escribir('textarea[data-aviso]', 'Un cliente: no guarda');
